CREATE TABLE public.ai_specialist_runs(id uuid PRIMARY KEY,user_id uuid NOT NULL,business_id uuid NOT NULL REFERENCES public.business_store(id) ON DELETE CASCADE,endpoints text[] NOT NULL,claimed text[] NOT NULL DEFAULT '{}',receipts jsonb NOT NULL DEFAULT '{}',expires_at timestamptz NOT NULL DEFAULT now()+interval '1 day',created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());GRANT SELECT ON public.ai_specialist_runs TO authenticated;GRANT ALL ON public.ai_specialist_runs TO service_role;ALTER TABLE public.ai_specialist_runs ENABLE ROW LEVEL SECURITY;CREATE POLICY specialist_run_read ON public.ai_specialist_runs FOR SELECT TO authenticated USING(user_id=auth.uid());CREATE TRIGGER specialist_run_touch BEFORE UPDATE ON public.ai_specialist_runs FOR EACH ROW EXECUTE FUNCTION public.touch_ai_record();CREATE FUNCTION ai_private.authorize_specialists(p_id uuid,p_business uuid,p_endpoint text) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE r public.ai_specialist_runs;eps text[];BEGIN IF auth.uid() IS NULL OR NOT EXISTS(SELECT 1 FROM public.business_store WHERE id=p_business AND user_id=auth.uid()) THEN RAISE EXCEPTION 'Business access denied' USING ERRCODE='42501';END IF;eps:=CASE WHEN p_endpoint IS NULL THEN ARRAY['market-research','competitor-analysis','business-plan','financial-model','marketing-strategy','ai-operations'] ELSE ARRAY[p_endpoint] END;IF NOT eps<@ARRAY['market-research','competitor-analysis','business-plan','financial-model','marketing-strategy','ai-operations'] THEN RAISE EXCEPTION 'Unsupported specialist';END IF;PERFORM pg_advisory_xact_lock(hashtextextended(p_id::text,0));SELECT * INTO r FROM public.ai_specialist_runs WHERE id=p_id;IF r.id IS NOT NULL THEN IF r.user_id<>auth.uid() OR r.business_id<>p_business OR r.endpoints<>eps THEN RAISE EXCEPTION 'Paid run context changed';END IF;RETURN r.id;END IF;PERFORM public.spend_credits(CASE WHEN p_endpoint IS NULL THEN 'convene' ELSE 'agent_rerun' END);INSERT INTO public.ai_specialist_runs(id,user_id,business_id,endpoints) VALUES(p_id,auth.uid(),p_business,eps);RETURN p_id;END $$;REVOKE ALL ON FUNCTION ai_private.authorize_specialists(uuid,uuid,text) FROM PUBLIC,anon;GRANT EXECUTE ON FUNCTION ai_private.authorize_specialists(uuid,uuid,text) TO authenticated;CREATE FUNCTION public.authorize_ai_specialists(p_id uuid,p_business uuid,p_endpoint text DEFAULT NULL) RETURNS uuid LANGUAGE sql SECURITY INVOKER SET search_path=public AS $$ SELECT ai_private.authorize_specialists(p_id,p_business,p_endpoint) $$;REVOKE ALL ON FUNCTION public.authorize_ai_specialists(uuid,uuid,text) FROM PUBLIC,anon;GRANT EXECUTE ON FUNCTION public.authorize_ai_specialists(uuid,uuid,text) TO authenticated;CREATE FUNCTION public.claim_ai_specialist(p_id uuid,p_user uuid,p_business uuid,p_endpoint text) RETURNS boolean LANGUAGE plpgsql SECURITY INVOKER SET search_path=public AS $$ BEGIN UPDATE public.ai_specialist_runs SET claimed=array_append(claimed,p_endpoint) WHERE id=p_id AND user_id=p_user AND business_id=p_business AND expires_at>now() AND p_endpoint=ANY(endpoints) AND NOT p_endpoint=ANY(claimed);RETURN FOUND;END $$;REVOKE ALL ON FUNCTION public.claim_ai_specialist(uuid,uuid,uuid,text) FROM PUBLIC,anon,authenticated;GRANT EXECUTE ON FUNCTION public.claim_ai_specialist(uuid,uuid,uuid,text) TO service_role;CREATE FUNCTION public.record_ai_specialist(p_id uuid,p_endpoint text,p_result jsonb) RETURNS void LANGUAGE sql SECURITY INVOKER SET search_path=public AS $$ UPDATE public.ai_specialist_runs SET receipts=receipts||jsonb_build_object(p_endpoint,p_result) WHERE id=p_id AND p_endpoint=ANY(claimed) $$;REVOKE ALL ON FUNCTION public.record_ai_specialist(uuid,text,jsonb) FROM PUBLIC,anon,authenticated;GRANT EXECUTE ON FUNCTION public.record_ai_specialist(uuid,text,jsonb) TO service_role;